<?php
require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/portal-layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');$role=($_POST['role']??'client')==='admin'?'admin':'client';$cid=$role==='admin'?null:(int)($_POST['client_id']??0);
if(!$n||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8||($role==='client'&&!$cid))flash_set('error','Revise os campos e use senha com pelo menos 8 caracteres.');
else try{$s=$pdo->prepare("INSERT INTO users(client_id,name,email,password_hash,role,active,created_at,updated_at)VALUES(?,?,?,?,?,1,NOW(),NOW())");$s->execute([$cid,$n,$email,password_hash($pw,PASSWORD_DEFAULT),$role]);flash_set('ok','Acesso criado com sucesso.');}catch(Throwable $e){
    flash_set('error','Erro ao criar acesso: '.$e->getMessage());
}header('Location: usuarios.php');exit;}
$clients=$pdo->query("SELECT id,name FROM clients WHERE active=1 ORDER BY name")->fetchAll();$users=$pdo->query("SELECT u.*,c.name client_name FROM users u LEFT JOIN clients c ON c.id=u.client_id ORDER BY u.id DESC")->fetchAll();portal_header('Usuários e acessos','usuarios');?><section class="panel"><span>ACESSOS</span><h2>Criar novo usuário</h2><form method="post" class="grid"><label>Nome<input name="name" required></label><label>E-mail<input type="email" name="email" required></label><label>Senha temporária<input type="password" name="password" minlength="8" required></label><label>Perfil<select name="role"><option value="client">Cliente</option><option value="admin">Administrador</option></select></label><label>Vincular ao cliente<select name="client_id"><option value="">Selecione</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><div><button>Criar acesso</button></div></form></section><section class="panel"><h2>Usuários cadastrados</h2><table><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Cliente</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['client_name']??'TSP')?></td><td><?=((int)($u['active']??1)===1)?'Ativo':'Inativo'?></td></tr><?php endforeach;?></table></section><?php portal_footer();?>